# -*- coding: utf-8 -*-
"""Author content/samples/wasiyyat-abi-hanifa-samti from the user-supplied text.

Bare/smart layers are COMPUTED from the full surface (same strip the validator
uses), so the tashkeel law cannot be broken by a transcription slip. Chapter 1
covers the frame + opening counsel; the rest of the received text waits in
research/sources/wasiyya-samti-arabic.txt.
"""
import json, re, pathlib

ROOT = pathlib.Path(__file__).resolve().parents[2]
PKG = ROOT / "content/samples/wasiyyat-abi-hanifa-samti"
(PKG / "chapters").mkdir(parents=True, exist_ok=True)

DIA = re.compile("[ً-ٰ]")
def bare(s): return DIA.sub("", s)

def tok(full, lex, pos, grammar, ar, en, tr, punct=None, qb=None, qa=None):
    t = {"surface": {"full": full, "smart": full, "bare": bare(full)},
         "lex": lex, "pos": pos}
    if grammar: t["grammar"] = grammar
    t["irab"] = {"ar": ar, "en": en, "tr": tr}
    if punct: t["punctAfter"] = punct
    if qb: t["quoteBefore"] = qb
    if qa: t["quoteAfter"] = qa
    return t

