  tok("الْأَحْدَاثَ","hadath","noun",["maful-bihi"],
      "مَفْعُولٌ بِهِ مَنْصُوبٌ — جَمْعُ «حَدَث»: الشَّابُّ.",
      "Object in nasb — plural of «hadath», a young man.",
      "Mensub mef'ûl — «حَدَث» (genç)in çoğuludur.", punct="."),
