S4.append({"id": "s26", "translation": {
 "en": "Hold fast to tact, patience, forbearance, good character, and breadth of heart.",
 "tr": "Müdârâya, sabra, tahammüle, güzel ahlâka ve gönül genişliğine sarıl."},
 "tokens": [
  tok("وَعَلَيْكَ","alayka","part",["ism-fil"],
      "الْوَاوُ عَاطِفَةٌ، وَ«عَلَيْكَ» اسْمُ فِعْلِ أَمْرٍ بِمَعْنَى «اِلْزَمْ»، وَالْفَاعِلُ مُسْتَتِرٌ (أَنْتَ).",
      "The waw links; «alayka» is a noun-verb of command meaning «hold to», its fa'il a concealed «you».",
      "و atıf harfi; «عليك», «اِلْزَمْ» manasında emir isim fiilidir, fâili gizli «sen»dir."),
  tok("بِالْمُدَارَاةِ","mudara","noun",["ism-fil","huruf-jarr"],
      "الْبَاءُ زَائِدَةٌ، وَ«الْمُدَارَاةِ» مَجْرُورٌ لَفْظًا فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ.",
      "The ba is extra; «tact» is jarr in form, in the position of nasb as the object.",
      "ب zâidedir; «المداراة» lafzen mecrûr, mahallen mensub mef'ûlün bihtir."),
  tok("وَالصَّبْرِ","sabr","noun",["atf-nasaq"],
      "مَعْطُوفٌ مَجْرُورٌ.","Joined, majrur.","Matuf; mecrûr."),
  tok("وَالِاحْتِمَالِ","ihtimal","noun",["atf-nasaq","masdar"],
      "مَعْطُوفٌ (مَصْدَرُ الاِفْتِعَالِ).","Joined — a Form VIII masdar.","Matuf (iftiâl masdarı)."),
  tok("وَحُسْنِ","husn","noun",["atf-nasaq","idafa-definiteness"],
      "مَعْطُوفٌ مُضَافٌ.","Joined, mudaf.","Matuf; muzâf."),
  tok("الْخُلُقِ","khuluq","noun",["idafa-definiteness"],
      "مُضَافٌ إِلَيْهِ.","Mudaf ilayh.","Muzâfun ileyh."),
  tok("وَسَعَةِ","saa","noun",["atf-nasaq","idafa-definiteness"],
      "مَعْطُوفٌ مُضَافٌ.","Joined, mudaf.","Matuf; muzâf."),
  tok("الصَّدْرِ","sadr","noun",["idafa-definiteness"],
      "مُضَافٌ إِلَيْهِ.","Mudaf ilayh.","Muzâfun ileyh.", punct="."),
 ]})

S4.append({"id": "s27", "translation": {
 "en": "Keep your clothes fresh, and use perfume generously.",
 "tr": "Elbiselerini yenile, güzel kokuyu bolca kullan."},
 "tokens": [
  tok("وَاسْتَجِدَّ","istajadda","verb",["atf-nasaq","form-x-verbs","doubled-verbs","imperative-amr"],
      "فِعْلُ أَمْرٍ مِنَ الاِسْتِفْعَالِ الْمُضَاعَفِ، مَبْنِيٌّ عَلَى الْفَتْحِ لِأَجْلِ الْإِدْغَامِ.",
      "An imperative of a DOUBLED Form X — built on fatha for the sake of the idgham.",
      "MUZÂAF istif'âl bâbından emir; idgam sebebiyle fetha üzere mebnîdir."),
  tok("ثِيَابَكَ","thawb","noun",["maful-bihi","idafa-definiteness"],
      "مَفْعُولٌ بِهِ، وَالْكَافُ مُضَافٌ إِلَيْهِ — جَمْعُ «ثَوْب».",
      "Object, with the kaf as mudaf ilayh — the plural of «garment».",
      "Mef'ûlün bih; ك muzâfun ileyh — «ثوب»un çoğuludur.", punct="،"),
  tok("وَأَكْثِرِ","akthara","verb",["atf-nasaq","form-iv-verbs","imperative-amr"],
      "مَعْطُوفٌ — أَمْرُ الْإِفْعَالِ، وَكُسِرَتِ الرَّاءُ لِالْتِقَاءِ السَّاكِنَيْنِ.",
      "Joined — a Form IV imperative; the ra takes kasra for the two sukuns.",
      "Matuf — if'âl emri; iki sâkin sebebiyle ر kesre almıştır."),
  tok("اسْتِعْمَالَ","istimal","noun",["maful-bihi","idafa-definiteness","masdar"],
      "مَفْعُولٌ بِهِ مُضَافٌ (مَصْدَرُ الاِسْتِفْعَالِ).",
      "Object and mudaf — a Form X masdar.",
      "Mef'ûlün bih, muzâf (istif'âl masdarı)."),
  tok("الطِّيبِ","tib","noun",["idafa-definiteness"],
      "مُضَافٌ إِلَيْهِ.","Mudaf ilayh.","Muzâfun ileyh.", punct="."),
 ]})

S4.append({"id": "s28", "translation": {
 "en": "Hold your gathering close — and let that be at known, fixed times.",
 "tr": "Meclisini yakın tut — ve bu, belli vakitlerde olsun."},
 "tokens": [
  tok("وَقَرِّبْ","qarraba","verb",["atf-nasaq","form-ii-verbs","imperative-amr"],
      "مَعْطُوفٌ — أَمْرُ التَّفْعِيلِ مَبْنِيٌّ عَلَى السُّكُونِ.",
      "Joined — a Form II imperative on sukun.",
      "Matuf — tef'îl emri, sükûn üzere mebnî."),
  tok("مَجْلِسَكَ","majlis","noun",["maful-bihi","idafa-definiteness"],
      "مَفْعُولٌ بِهِ وَالْكَافُ مُضَافٌ إِلَيْهِ — اسْمُ مَكَانٍ.",
      "Object with the kaf as mudaf ilayh — a noun of place.",
      "Mef'ûlün bih; ك muzâfun ileyh — ism-i mekândır.", punct="،"),
  tok("وَلْيَكُنْ","kana","verb",["lam-amr","kana-wa-akhawatuha","hollow-verbs"],
      "الْوَاوُ عَاطِفَةٌ وَاللَّامُ لَامُ الْأَمْرِ (سُكِّنَتْ بَعْدَ الْوَاوِ)، وَ«يَكُنْ» مُضَارِعٌ نَاقِصٌ مَجْزُومٌ حُذِفَتْ وَاوُهُ لِالْتِقَاءِ السَّاكِنَيْنِ.",
      "The waw links; the lam is the lam of command (silenced after waw); «let it be» is a kana-class mudari' in jazm, its waw dropped where two sukuns met.",
      "و atıf; ل emir lâmıdır (vâvdan sonra sâkin okunur); «يَكُنْ» meczum nâkıs muzâridir, iki sâkin sebebiyle vâv'ı düşmüştür."),
  tok("ذٰلِكَ","dhalika","pron",["kana-wa-akhawatuha"],
      "اسْمُ «يَكُنْ» فِي مَحَلِّ رَفْعٍ.","The ism of «let it be», in the position of raf'.","«يكن»ün ismi; mahallen merfûdur."),
  tok("فِي","fi","prep",["huruf-jarr"],
      "حَرْفُ جَرٍّ.","A jarr letter.","Cer harfidir."),
  tok("أَوْقَاتٍ","waqt","noun",["huruf-jarr","kana-wa-akhawatuha"],
      "مَجْرُورٌ، وَالْجَارُّ وَالْمَجْرُورُ مُتَعَلِّقٌ بِخَبَرِ «يَكُنْ» الْمَحْذُوفِ.",
      "Majrur; the jarr-phrase attaches to the omitted khabar of «let it be».",
      "Mecrûr; câr-mecrûr, «يكن»ün mahzuf haberine müteallıktır."),
  tok("مَعْلُومَةٍ","malum","noun",["naat-sifa","ism-maful"],
      "صِفَةٌ مَجْرُورَةٌ — اسْمُ مَفْعُولٍ.",
      "A sifa in jarr — an ism maf'ul.",
      "Sıfat, mecrûr — ism-i mef'ûldür.", punct="."),
 ]})

