  tok("وَفِيهَا","fi","prep",["huruf-jarr","anwa-al-khabar"],
      "جَارٌّ وَمَجْرُورٌ خَبَرٌ مُقَدَّمٌ.",
      "Jarr-majrur as a FRONTED khabar.",
      "Câr-mecrûr; mukaddem haberdir."),
  tok("قَوْلٌ","qawl","noun",["mubtada-khabar"],
      "مُبْتَدَأٌ مُؤَخَّرٌ مَرْفُوعٌ.","A postponed mubtada in raf'.","Muahhar mübteda; merfûdur."),
