# ---------------------------------------------------------------- Chapter 10
# الْوَدَاعُ — the last of the counsel (accept for them what you accept for
# yourself; lead with good intention; live with people of every creed as they
# live with you) and the farewell itself: «be to me as a son, for I am to you
# as a father». The received text writes ما لا يكلفوك; the classical form
# يُكَلِّفُونَكَ is printed and the divergence is recorded in the manifest.
