# ---------------------------------------------------------------- Chapter 11
# الْخَاتِمَةُ — al-Samti's own epilogue: the dinars and the escort to the
# Euphrates, Basra won over, the madhhab spreading, the letters that kept
# coming until the Imam died — and the closing benediction. The obscure clause
# «وانتقضت المجالس» of the received text is left for scholarly review.
