S11.append({"id": "s79", "translation": {
 "en": "and the school of al-Hasan and of Ibn Sirin passed out of use — may Allah be pleased with them both.",
 "tr": "Hasan'ın ve İbn Sîrîn'in mezhebi ise geçerlikten düştü — Allah ikisinden de razı olsun."},
 "tokens": [
  tok("وَسَقَطَ","saqata","verb",["atf-nasaq"],
      "مَعْطُوفٌ — مَاضٍ، وَمَعْنَاهُ هُنَا: انْقَرَضَ.",
      "Joined — a past; here it means «died out».",
      "Matuf — mâzî; buradaki manası «inkırâz etti»dir."),
  tok("مَذْهَبُ","madhhab","noun",["fail","idafa-definiteness"],
      "فَاعِلٌ مَرْفُوعٌ مُضَافٌ.","Fa'il in raf', mudaf.","Merfû fâil; muzâftır."),
  tok("الْحَسَنِ","hasan","propn",["idafa-definiteness"],
      "مُضَافٌ إِلَيْهِ مَجْرُورٌ — هُوَ الْحَسَنُ الْبَصْرِيُّ.",
      "Mudaf ilayh in jarr — al-Hasan al-Basri.",
      "Mecrur muzâfun ileyh — Hasan-ı Basrî'dir."),
  tok("وَابْنِ","ibn","noun",["atf-nasaq","idafa-definiteness"],
      "مَعْطُوفٌ مَجْرُورٌ وَهُوَ مُضَافٌ.",
      "Joined, in jarr, mudaf.",
      "Matuf; mecrur ve muzâftır."),
  tok("سِيرِينَ","sirin","propn",["idafa-definiteness","mamnu-min-sarf"],
      "مُضَافٌ إِلَيْهِ مَجْرُورٌ بِالْفَتْحَةِ — أَعْجَمِيٌّ مَمْنُوعٌ مِنَ الصَّرْفِ.",
      "Mudaf ilayh in jarr by fatha — a foreign name, barred from tanwin.",
      "Fetha ile mecrur muzâfun ileyh — a'cemî, gayr-i munsariftir."),
  tok("رَضِيَ","radiya","verb",["naqis-verbs"],
      "مَاضٍ — جُمْلَةٌ دُعَائِيَّةٌ مُعْتَرِضَةٌ.",
      "A past — an interposed clause of prayer.",
      "Mâzî — muterize duâ cümlesidir."),
  tok("اللهُ","allah","propn",["fail"],
      "لَفْظُ الْجَلَالَةِ فَاعِلٌ.","The Name of Majesty, fa'il.","Lafza-i celâl; fâildir."),
  tok("عَنْهُمَا","an-prep","part",["huruf-jarr"],
      "جَارٌّ وَمَجْرُورٌ — ضَمِيرُ الْمُثَنَّى.",
      "A jarr-phrase — the dual pronoun.",
      "Câr-mecrûr — tesniye zamiridir.", punct="."),
 ]})

S11.append({"id": "s80", "translation": {
 "en": "And the letters of Abu Hanifa never ceased coming to me, until he died — may Allah the Exalted have mercy on him.",
 "tr": "Ebû Hanîfe'nin mektupları, vefat edinceye kadar bana gelmeye devam etti — Allah Teâlâ ona rahmet etsin."},
 "tokens": [
  tok("فَمَا","ma-nafiya","part",["ma-la-mushabbaha"],
      "الْفَاءُ عَاطِفَةٌ وَ«مَا» نَافِيَةٌ.",
      "The fa joins; «ma» negates.",
      "Fâ atıftır; «ما» nâfiyedir."),
  tok("زَالَتْ","zala","verb",["kana-wa-akhawatuha","hollow-verbs"],
      "«زَالَ» أُخْتُ «كَانَ» الْمُلَازِمَةُ لِلنَّفْيِ، وَتَاءُ التَّأْنِيثِ.",
      "«Zala», kana's sister that never leaves negation, with the feminine ta.",
      "Nefyden ayrılmayan «كان» kız kardeşi «زال» ve te'nis tâ'sı."),
  tok("كُتُبُ","kitab","noun",["kana-wa-akhawatuha","idafa-definiteness"],
      "اسْمُ «زَالَ» مَرْفُوعٌ وَهُوَ مُضَافٌ.",
      "Zala's noun in raf', mudaf.",
      "«زال»ın ismi; merfû ve muzâftır."),
  tok("أَبِي","ab","noun",["five-nouns","idafa-definiteness"],
      "مُضَافٌ إِلَيْهِ مَجْرُورٌ بِالْيَاءِ.",
      "Mudaf ilayh in jarr by the ya.",
      "Yâ ile mecrur muzâfun ileyhtir."),
  tok("حَنِيفَةَ","hanifa","propn",["idafa-definiteness","mamnu-min-sarf"],
      "مُضَافٌ إِلَيْهِ مَجْرُورٌ بِالْفَتْحَةِ.",
      "Mudaf ilayh in jarr by fatha.",
      "Fetha ile mecrur muzâfun ileyhtir."),
  tok("تَجِيئُنِي","jaa","verb",["kana-wa-akhawatuha","hollow-verbs","anwa-al-khabar"],
      "مُضَارِعٌ، وَالنُّونُ لِلْوِقَايَةِ وَالْيَاءُ مَفْعُولٌ — وَالْجُمْلَةُ خَبَرُ «زَالَ» فِي مَحَلِّ نَصْبٍ.",
      "A mudari'; protective nun, the ya its object — the clause is zala's khabar, in nasb's position.",
      "Muzâri; nûn vikaye, yâ mef'ûldür — cümle «زال»ın haberi olarak mahallen mensubdur."),
  tok("إِلَى","ila","part",["huruf-jarr","an-masdariyya"],
      "حَرْفُ جَرٍّ — وَمَا بَعْدَهُ مَصْدَرٌ مُؤَوَّلٌ: إِلَى مَوْتِهِ.",
      "A jarr particle — what follows resolves to a masdar: «until his death».",
      "Cer harfidir — sonrası müevvel masdardır: «vefatına kadar»."),
  tok("أَنْ","an-masdariyya-lex","part",["an-masdariyya"],
      "مَصْدَرِيَّةٌ.","The masdar-maker.","Masdariyedir."),
  tok("مَاتَ","mata-die","verb",["hollow-verbs"],
      "مَاضٍ — أَجْوَفُ — وَالْمَصْدَرُ الْمُؤَوَّلُ مَجْرُورٌ بِإِلَى.",
      "A past — hollow — the resolved masdar in jarr after «ila».",
      "Mâzî — ecvef — müevvel masdar «إلى» ile mecrurdur."),
  tok("رَحِمَهُ","rahima","verb",["maful-bihi"],
      "مَاضٍ وَالْهَاءُ مَفْعُولٌ — جُمْلَةٌ دُعَائِيَّةٌ.",
      "A past, the ha its object — a clause of prayer.",
      "Mâzî; هُ mef'ûldür — duâ cümlesidir."),
  tok("اللهُ","allah","propn",["fail"],
      "فَاعِلٌ مَرْفُوعٌ.","Fa'il in raf'.","Merfû fâildir."),
  tok("تَعَالَى","taala","verb",["naqis-verbs","form-vi-verbs"],
      "مَاضٍ — ثَنَاءٌ مُعْتَرِضٌ.","A past — interposed praise.","Mâzî — muterize senâdır.", punct="."),
 ]})

S11.append({"id": "s81", "translation": {
 "en": "So blessings on you, from such a righteous teacher and righteous master!",
 "tr": "Böyle sâlih bir muallimden, sâlih bir üstaddan sana ne mutlu!"},
 "tokens": [
  tok("فَهَنِيئًا","hani","noun",["maful-mutlaq"],
      "الْفَاءُ اسْتِئْنَافِيَّةٌ وَ«هَنِيئًا» مَنْصُوبٌ بِفِعْلٍ مَحْذُوفٍ لَا يُذْكَرُ: هَنُؤَ لَكَ.",
      "The fa opens anew; «hani'an» in nasb by a verb suppressed and never spoken: «may it be wholesome for you».",
      "Fâ isti'nâfiyedir; «هنيئًا», söylenmeyen mahzuf bir fiille mensubdur: «sana âfiyet olsun»."),
  tok("لَكَ","li","part",["huruf-jarr"],
      "جَارٌّ وَمَجْرُورٌ.","A jarr-phrase.","Câr-mecrûrdur."),
  tok("مِنْ","min","part",["huruf-jarr"],
      "حَرْفُ جَرٍّ لِلْبَيَانِ.","The jarr particle of specification.","Beyân için cer harfidir."),
  tok("مُعَلِّمٍ","muallim","noun",["huruf-jarr","ism-fail"],
      "مَجْرُورٌ — اسْمُ فَاعِلٍ مِنَ التَّفْعِيلِ.",
      "In jarr — the Form II active participle.",
      "Mecrur — tef'îl bâbının ism-i fâilidir."),
  tok("صَالِحٍ","salih","noun",["naat-sifa","ism-fail"],
      "نَعْتٌ مَجْرُورٌ.","A na't in jarr.","Mecrur na'ttır."),
  tok("وَأُسْتَاذٍ","ustadh","noun",["atf-nasaq"],
      "مَعْطُوفٌ مَجْرُورٌ.","Joined, in jarr.","Matuf; mecrurdur."),
  tok("صَالِحٍ","salih","noun",["naat-sifa"],
      "نَعْتٌ مَجْرُورٌ.","A na't in jarr.","Mecrur na'ttır.", punct="."),
 ]})

S11.append({"id": "s82", "translation": {
 "en": "And who is there for us like him? — may Allah be pleased with him.",
 "tr": "Bizim için onun gibisi kim var ki? — Allah ondan razı olsun."},
 "tokens": [
  tok("فَمَنْ","man-istifham","pron",["mubtada-khabar"],
      "الْفَاءُ اسْتِئْنَافِيَّةٌ وَ«مَنْ» اسْتِفْهَامٌ إِنْكَارِيٌّ بِمَعْنَى النَّفْيِ — مُبْتَدَأٌ فِي مَحَلِّ رَفْعٍ.",
      "The fa opens anew; «man» is the denying question that means «no one» — mubtada in raf's position.",
      "Fâ isti'nâfiyedir; «مَنْ» nefy manasında inkârî istifhamdır — mahallen merfû mübtedadır."),
  tok("لَنَا","li","part",["huruf-jarr","mubtada-khabar"],
      "جَارٌّ وَمَجْرُورٌ خَبَرٌ.",
      "A jarr-phrase as the khabar.",
      "Haber olan câr-mecrûrdur."),
  tok("مِثْلُهُ","mithl","noun",["badal","idafa-definiteness"],
      "بَدَلٌ مِنَ «مَنْ» مَرْفُوعٌ، وَالْهَاءُ مُضَافٌ إِلَيْهِ — وَيَصِحُّ مُبْتَدَأً وَ«لَنَا» خَبَرُهُ.",
      "Badal of «man» in raf', the ha its mudaf ilayh — reading it as the mubtada with «for us» its khabar is also sound.",
      "«مَنْ»den bedel; merfûdur, هُ muzâfun ileyhtir — mübteda okunup «لنا»nın haber olması da sahihtir."),
  tok("رَضِيَ","radiya","verb",["naqis-verbs"],
      "مَاضٍ — جُمْلَةٌ دُعَائِيَّةٌ.","A past — a clause of prayer.","Mâzî — duâ cümlesidir."),
  tok("اللهُ","allah","propn",["fail"],
      "فَاعِلٌ مَرْفُوعٌ.","Fa'il in raf'.","Merfû fâildir."),
  tok("عَنْهُ","an-prep","part",["huruf-jarr"],
      "جَارٌّ وَمَجْرُورٌ.","A jarr-phrase.","Câr-mecrûrdur.", punct="."),
 ]})

