# Merge with what's on disk: the paradigm bank (sarf_gen.py output) lives in
# morphology.json too, and regenerating the story must not clobber it. This
# script's own entries win on conflict.
_mpath = PKG / "morphology.json"
if _mpath.exists():
    _prev = json.loads(_mpath.read_text(encoding="utf-8")).get("verbs", {})
    _prev.update(MORPH["verbs"])
    MORPH = {"verbs": _prev}
_mpath.write_text(json.dumps(MORPH, ensure_ascii=False, indent=1), encoding="utf-8")

ALL = S + S2 + S3 + S4 + S5 + S6 + S7 + S8 + S9 + S10 + S11
used = {t["lex"] for s in ALL for t in s["tokens"]}
dead = set(GLOSS) - used
missing = used - set(GLOSS)
print("tokens:", sum(len(s["tokens"]) for s in ALL), "gloss:", len(GLOSS),
      "jumal:", sum(len(s.get("jumal", [])) for s in ALL),
      "dead:", sorted(dead), "missing:", sorted(missing))
